import{_ as l,a0 as o,w as p,s as r,ao as d,I as n,a1 as i,A as a,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何在 Linux 下锁住键盘和鼠标而不锁屏 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 下锁住键盘和鼠标而不锁屏 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 下锁住键盘和鼠标而不锁屏 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 下锁住键盘和鼠标而不锁屏 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180817 How To Lock The Keyboard And Mouse, But Not The Screen In Linux","title":"如何在 Linux 下锁住键盘和鼠标而不锁屏","tag":"201810","desc":""},"relativePath":"201810/20180817 How To Lock The Keyboard And Mouse, But Not The Screen In Linux.md","filePath":"[post].md"}'),h={name:"201810/20180817 How To Lock The Keyboard And Mouse, But Not The Screen In Linux.md"};function c(g,s,u,k,b,x){const e=o("Link");return p(),r("div",null,[s[16]||(s[16]=d(`<h1 id="如何在-linux-下锁住键盘和鼠标而不锁屏" tabindex="-1">如何在 Linux 下锁住键盘和鼠标而不锁屏 <a class="header-anchor" href="#如何在-linux-下锁住键盘和鼠标而不锁屏" aria-label="Permalink to “如何在 Linux 下锁住键盘和鼠标而不锁屏”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/09/Lock-The-Keyboard-And-Mouse-720x340.jpg" alt=""></p><p>我四岁的侄女是个好奇的孩子，她非常喜爱“阿凡达”电影，当阿凡达电影在播放时，她是如此的专注，好似眼睛粘在了屏幕上。但问题是当她观看电影时，她经常会碰到键盘上的某个键或者移动了鼠标，又或者是点击了鼠标的按钮。有时她非常意外地按了键盘上的某个键，从而将电影关闭或者暂停了。所以我就想找个方法来将键盘和鼠标都锁住，但屏幕不会被锁住。幸运的是，我在 Ubuntu 论坛上找到了一个完美的解决方法。假如在你正看着屏幕上的某些重要的事情时，你不想让你的小猫或者小狗在你的键盘上行走，或者让你的孩子在键盘上瞎搞一气，那我建议你试试 <strong>xtrlock</strong> 这个工具。它很简单但非常实用，你可以锁定屏幕的显示直到用户在键盘上输入自己设定的密码（LCTT 译注：就是用户自己的密码，例如用来打开屏保的那个密码，不需要单独设定）。在这篇简单的教程中，我将为你展示如何在 Linux 下锁住键盘和鼠标，而不锁掉屏幕。这个技巧几乎可以在所有的 Linux 操作系统中生效。</p><h3 id="安装-xtrlock" tabindex="-1">安装 xtrlock <a class="header-anchor" href="#安装-xtrlock" aria-label="Permalink to “安装 xtrlock”">​</a></h3><p>xtrlock 软件包在大多数 Linux 操作系统的默认软件仓库中都可以获取到。所以你可以使用你安装的发行版的包管理器来安装它。</p><p>在 <strong>Arch Linux</strong> 及其衍生发行版中，运行下面的命令来安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S xtrlock</span></span></code></pre></div><p>在 <strong>Fedora</strong> 上使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install xtrlock</span></span></code></pre></div><p>在 <strong>RHEL、CentOS</strong> 上使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install xtrlock</span></span></code></pre></div><p>在 <strong>SUSE/openSUSE</strong> 上使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo zypper install xtrlock</span></span></code></pre></div><p>在 <strong>Debian、Ubuntu、Linux Mint</strong> 上使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install xtrlock</span></span></code></pre></div><h3 id="使用-xtrlock-锁住键盘和鼠标但不锁屏" tabindex="-1">使用 xtrlock 锁住键盘和鼠标但不锁屏 <a class="header-anchor" href="#使用-xtrlock-锁住键盘和鼠标但不锁屏" aria-label="Permalink to “使用 xtrlock 锁住键盘和鼠标但不锁屏”">​</a></h3><p>安装好 xtrlock 后，你需要根据你的选择来创建一个快捷键，通过这个快捷键来锁住键盘和鼠标。</p><p>（LCTT 译注：译者在自己的系统（Arch + Deepin）中发现这里的到下面创建快捷键的部分可以不必做，依然生效。）</p><p>在 <code>/usr/local/bin</code> 目录下创建一个名为 <code>lockkbmouse</code> 的新文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /usr/local/bin/lockkbmouse</span></span></code></pre></div><p>然后将下面的命令添加到这个文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>sleep 1 &amp;&amp; xtrlock</span></span></code></pre></div><p>保存并关闭这个文件。</p><p>然后使用下面的命令来使得它可以被执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod a+x /usr/local/bin/lockkbmouse</span></span></code></pre></div><p>接着，我们就需要创建快捷键了。</p><h4 id="创建快捷键" tabindex="-1">创建快捷键 <a class="header-anchor" href="#创建快捷键" aria-label="Permalink to “创建快捷键”">​</a></h4><p><strong>在 Arch Linux MATE 桌面中</strong></p><p>依次点击 “System -&gt; Preferences -&gt; Hardware -&gt; keyboard Shortcuts”</p><p>然后点击 “Add” 来创建快捷键。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/09/Keyboard-Shortcuts_001.png" alt=""></p><p>首先键入你的这个快捷键的名称，然后将下面的命令填入命令框中，最后点击 “Apply” 按钮。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bash -c &quot;sleep 1 &amp;&amp; xtrlock&quot;</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/09/Keyboard-Shortcuts_002.png" alt=""></p><p>为了能够给这个快捷键赋予快捷方式，需要选中它或者双击它然后输入你选定的快捷键组合，例如我使用 <code>Alt+k</code> 这组快捷键。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/09/Keyboard-Shortcuts_003.png" alt=""></p><p>如果要清除这个快捷键组合，按住 <code>BACKSPACE</code> 键就可以了。完成后，关闭键盘设定窗口。</p><p><strong>在 Ubuntu GNOME 桌面中</strong></p><p>依次进入 “System Settings -&gt; Devices -&gt; Keyboard”，然后点击 “+” 这个符号。</p><p>键入你快捷键的名称并将下面的命令加到命令框里面，然后点击 “Add” 按钮。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bash -c &quot;sleep 1 &amp;&amp; xtrlock&quot;</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/Add-xtrlock-shortcut.png" alt=""></p><p>接下来为这个新建的快捷键赋予快捷方式。我们只需要选择或者双击 “Set shortcut” 这个按钮就可以了。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/set-shortcut-key-1.png" alt=""></p><p>然后你将看到下面的一屏。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/set-shortcut-key-2.png" alt=""></p><p>输入你选定的快捷键组合，例如我使用 <code>Alt+k</code>。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/set-shortcut-key-3.png" alt=""></p><p>如果要清除这个快捷键组合，则可以按 <code>BACKSPACE</code> 这个键。这样快捷键便设定好了，完成这个后，关闭键盘设定窗口。</p><p>从现在起，每当你输入刚才设定的快捷键（在我们的示例中是 <code>ATL+K</code>），鼠标的指针便会变成一个挂锁的模样。现在，键盘和鼠标便被锁定了，这时你便可以自在地观看你的电影或者做其他你想做的事儿。即便是你的孩子或者宠物碰了键盘上的某些键或者点击了鼠标，这些操作都不会起作用。</p><p>因为 <code>xtrlock</code> 已经在工作了。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/xtrclock-1.png" alt=""></p><p>你看到了那个小的锁按钮了吗？它意味着键盘和鼠标已经被锁定了。即便你移动这个锁按钮，也不会发生任何事情。后台的任务在一直执行，直到你将屏幕解除，然后手动停掉运行中的任务。</p><h3 id="将键盘和鼠标解锁" tabindex="-1">将键盘和鼠标解锁 <a class="header-anchor" href="#将键盘和鼠标解锁" aria-label="Permalink to “将键盘和鼠标解锁”">​</a></h3><p>要将键盘和鼠标解锁，只需要输入你的密码然后敲击回车键就可以了，在输入的过程中你将看不到密码。只需要输入然后敲回车键就可以了。在你输入了正确的密码后，鼠标和键盘就可以再工作了。假如你输入了一个错误的密码，你将听到警告声。按 <code>ESC</code> 来清除输入的错误密码，然后重新输入正确的密码。要去掉未完全输入完的密码中的一个字符，只需要按 <code>BACKSPACE</code> 或者 <code>DELETE</code> 键就可以了。</p><h3 id="要是我被永久地锁住了怎么办" tabindex="-1">要是我被永久地锁住了怎么办？ <a class="header-anchor" href="#要是我被永久地锁住了怎么办" aria-label="Permalink to “要是我被永久地锁住了怎么办？”">​</a></h3><p>以防你被永久地锁定了屏幕，切换至一个 TTY（例如 <code>CTRL+ALT+F2</code>）然后运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo killall xtrlock</span></span></code></pre></div><p>或者你还可以使用 <code>chvt</code> 命令来在 TTY 和 X 会话之间切换。</p><p>例如，如果要切换到 TTY1，则运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chvt 1</span></span></code></pre></div><p>要切换回 X 会话，则键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chvt 7</span></span></code></pre></div><p>不同的发行版使用了不同的快捷键组合来在不同的 TTY 间切换。请参考你安装的对应发行版的官方网站了解更多详情。</p><p>如果想知道更多 xtrlock 的信息，请参考 man 页：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man xtrlock</span></span></code></pre></div><p>那么这就是全部了。希望这个指南可以帮到你。假如你发现这个指南很有用，请花点时间将这个指南共享到你的朋友圈并支持我们（OSTechNix）。</p><p><strong>资源：</strong></p>`,68)),n("ul",null,[n("li",null,[i(e,{href:"https://ubuntuforums.org/showthread.php?t=993800"},{default:a(()=>[...s[0]||(s[0]=[n("strong",null,"Ubuntu 论坛",-1)])]),_:1})])]),s[17]||(s[17]=n("hr",null,null,-1)),n("p",null,[s[2]||(s[2]=t("via: ",-1)),i(e,{href:"https://www.ostechnix.com/lock-keyboard-mouse-not-screen-linux/"},{default:a(()=>[...s[1]||(s[1]=[t("https://www.ostechnix.com/lock-keyboard-mouse-not-screen-linux/",-1)])]),_:1})]),n("p",null,[s[7]||(s[7]=t("作者：",-1)),i(e,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[3]||(s[3]=[t("SK",-1)])]),_:1}),s[8]||(s[8]=t(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[4]||(s[4]=[t("lujun9972",-1)])]),_:1}),s[9]||(s[9]=t(" 译者：",-1)),i(e,{href:"https://github.com/FSSlc"},{default:a(()=>[...s[5]||(s[5]=[t("FSSlc",-1)])]),_:1}),s[10]||(s[10]=t(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[6]||(s[6]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[11]||(s[11]=[t("LCTT",-1)])]),_:1}),s[14]||(s[14]=t(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:a(()=>[...s[12]||(s[12]=[t("Linux中国",-1)])]),_:1}),s[15]||(s[15]=t(" 荣誉推出",-1))])])}const w=l(h,[["render",c]]);export{y as __pageData,w as default};
